// A single function for both compile-time and runtime.
constexpr int pow(int base, int exp) noexcept {
  // In C++14 and later, loops and variables are allowed.
  auto result = 1;
  for (int i = 0; i < exp; ++i) result *= base;
  return result;
}

// Compile-time usage: array size must be a compile-time constant
constexpr auto num_conditions = 5;
std::array<int, pow(3, num_conditions)> results; // pow() is evaluated at compile time

// Runtime usage: values are not known at compile time
int runtime_base = 2;
int runtime_exp = 10;
int runtime_result = pow(runtime_base, runtime_exp); // pow() is evaluated at runtime
